    "Dynamic prices, solar, battery, EV and inverter automations are configured once for the whole home under Energy settings.": "Dynamische prijzen, zonne-energie, accu, EV en omvormer automatiseringen zijn eenmaal geconfigureerd voor het hele huis onder Energie-instellingen.",
