    "State-of-charge sensor": "Status-van-laadsensor",
    "Steer devices around prices and solar production. Loads can run in cheap or surplus hours, while inverter output can be reduced safely to avoid unwanted export. Each setup creates a normal, editable Home Assistant automation with restart recovery and fail-safe behaviour.": "Stuur apparaten rond prijzen en zonneproductie. Laden kunnen lopen in goedkope of overtollige uren, terwijl omvormer output veilig kan worden verminderd om ongewenste export te voorkomen. Elke setup creëert een normale, bewerkbare Home Assistant-automatisering met herstartherstel en veilig gedrag.",
    "Surplus needed": "Noodzakelijk overschot",
    "Switch a deferrable load (boiler, pump, ventilation) on during the cheapest contiguous block of the day and off when it ends.": "Schakel een uitstelbare belasting (kooktoestel, pomp, ventilatie) in tijdens het goedkoopste aaneengesloten blok van de dag en uit wanneer het eindigt.",
    "Switch a load off when the price level hits its daily peak and back on when it drops. Trims the most expensive hours.": "Schakel een lading uit wanneer het prijsniveau raakt zijn dagelijkse piek en terug op wanneer het daalt. De duurste uren.",
    "Switch a load on when the house exports more than it needs, and off when you would start importing - with hysteresis + dwell so it does not flap.": "Schakel een lading in wanneer het huis exporteert meer dan het nodig heeft, en uit wanneer je zou beginnen met importeren - met hysteresis + wonen, zodat het niet flap.",
