    "Use the lowest value accepted by the inverter. A small non-zero limit is safer for many models.": "Gebruik de laagste waarde die door de inverter wordt geaccepteerd. Een kleine niet-nullimiet is veiliger voor veel modellen.",
    "Used for the smart-savings estimate and the fuse guard below.": "Gebruikt voor de schatting van smart-spaargeld en de zekeringbeschermer hieronder.",
    "Used to stop charging at the target and to protect the reserve in battery arbitrage.": "Gebruikt om te stoppen met laden op het doel en om de reserve te beschermen in batterij arbitrage.",
