    "Your API key works, but the selected location has no active energy contract, so there are no prices to plan against. Add or activate a contract in your SmartHomeShop account, or pick another location in Settings.": "Uw API sleutel werkt, maar de geselecteerde locatie heeft geen actief energiecontract, dus er zijn geen prijzen te plannen tegen. Voeg een contract toe of activeer het in je SmartHomeShop-account, of kies een andere locatie in Instellingen.",
    "Your P1 meter covers the grid. If you have solar panels or a home battery, connect their sensors so the Energy tab shows real surplus and state of charge. You can always do this later from Settings.": "Uw P1 meter bedekt het raster. Als u zonnepanelen of een thuisbatterij hebt, sluit dan hun sensoren aan zodat het tabblad Energie een echt overschot en opgeladen toestand laat zien. U kunt dit altijd later doen vanuit Instellingen.",
    "Your P1 meter only sees the grid. Connect your solar and battery entities (you already have them in Home Assistant) so we can see real solar surplus and your battery's charge level.": "Uw P1 meter ziet alleen het raster. Sluit uw zonne- en batterij-eenheden aan (u hebt ze al in Home Assistant) zodat we echt zonneoverschot en het laadniveau van uw batterij kunnen zien.",
    "Your polygon zone is drawn! Choose what type this zone should be.": "Je polygon zone is getekend! Kies welk type deze zone moet zijn.",
