    "{count} hours ago": "vor {count} Stunden",
    "{count} day ago": "vor {count} Tag",
    "{count} days ago": "vor {count} Tagen",
    "Open {name}": "{name} öffnen",
    "Rename {name}": "{name} umbenennen",
    "Delete {name}": "{name} löschen",
    "Place {name}": "{name} platzieren",
    "Could not set {name} to {mode} mode.": "{name} konnte nicht in den Modus {mode} versetzt werden.",
    "{name} has {count} vertices. LD2450 and LD2460 polygons support at most 20.": "{name} hat {count} Eckpunkte. LD2450- und LD2460-Polygone unterstützen höchstens 20 Punkte.",
    "Remove {name}?": "{name} entfernen?",
    "Remove {name}": "{name} entfernen",
    "Show {name} in SmartHomeShop again": "{name} wieder in SmartHomeShop anzeigen",
    "{name} is visible in SmartHomeShop again.": "{name} ist wieder in SmartHomeShop sichtbar.",
    "Could not restore {name}.": "{name} konnte nicht wiederhergestellt werden.",
    "Type": "Eingeben:",
    "to confirm permanent removal": "um das endgültige Entfernen zu bestätigen",
    "Hidden devices": "Ausgeblendete Geräte",
    "wall": "Wand",
