    "Delete \"{name}\" and its automation?": "\"{name}\" und die zugehörige Automatisierung löschen?",
    "{name} is currently set to {current}. Change the radar hardware to {required} mode for this {mounting} mounting?": "{name} ist derzeit auf {current} eingestellt. Die Radarhardware für diese {mounting}-Montage auf den Modus {required} umstellen?",
    "\"Cheap\" here means below the daily average price, not the single cheapest window. Use \"Run in the cheapest hours\" for that.": "\"Billig\" bedeutet hier unter dem täglichen Durchschnittspreis, nicht das einzige billigste Fenster. Verwenden Sie dafür \"Laufen Sie in den billigsten Stunden\".",
    "(free with any account) and paste it here.": "(frei mit jedem Konto) und fügen Sie es hier ein.",
