    "All four points are ready. Select a point above to measure it again, or save this detection area.": "Alle vier Punkte sind fertig. Wählen Sie einen Punkt oben, um ihn erneut zu messen, oder speichern Sie diesen Detektionsbereich.",
    "All grid readings and smart-energy features on this page follow this meter.": "Alle Rasterwerte und Smart-Energy-Funktionen auf dieser Seite folgen diesem Messgerät.",
    "All live entities from this device disappear from Home Assistant. Cards and automations that reference them stop working. Recorder history may remain until Home Assistant purges it.": "Alle Live-Entitäten von diesem Gerät verschwinden aus Home Assistant. Karten und Automatisierungen, die auf sie verweisen, funktionieren nicht mehr. Recorder Geschichte kann bleiben, bis Home Assistant es bereinigt.",
