    "Click for the second point. After 2 points you can create an entry line or continue for a polygon zone.": "Klicken Sie für den zweiten Punkt. Nach 2 Punkten können Sie eine Einstiegszeile erstellen oder für eine Polygonzone fortfahren.",
    "Click to add corners. Click the first point to close the room. Esc cancels, Ctrl+Z undoes.": "Klicken Sie, um Ecken hinzuzufügen. Klicken Sie auf den ersten Punkt, um den Raum zu schließen. Esc annulliert, Ctrl+ Z undoes.",
    "Click to add points. Click the green point to close. Drag points to move them. Right-click a point to delete it.": "Klicken Sie, um Punkte hinzuzufügen. Klicken Sie auf den grünen Punkt, um zu schließen. Ziehen Sie Punkte, um sie zu bewegen. Klicken Sie mit der rechten Maustaste auf einen Punkt, um ihn zu löschen.",
