    "Compare energy contracts against real spot prices and your own usage in your SmartHomeShop account, including a full savings analysis.": "Vergleichen Sie Energieverträge mit realen Spotpreisen und Ihrer eigenen Nutzung in Ihrem SmartHomeShop-Konto, einschließlich einer vollständigen Einsparungsanalyse.",
