    "Connect": "Anschluss",
    "Connect once here to use your fixed, variable or dynamic energy contract across SmartHomeShop Energy. The integration keeps working locally without an account.": "Verbinden Sie sich einmal hier, um Ihren festen, variablen oder dynamischen Energievertrag über SmartHomeShop Energy zu nutzen. Die Integration funktioniert lokal ohne Konto.",
    "Connect or select a P1 meter before linking the Home Assistant Energy Dashboard.": "Schließen Sie ein P1-Messgerät an oder wählen Sie es aus, bevor Sie das Home Assistant Energy Dashboard verbinden.",
    "Connect or select a P1 meter first to configure smart energy automations.": "Schließen oder wählen Sie zuerst ein P1-Messgerät aus, um intelligente Energieautomatisierungen zu konfigurieren.",
    "Connect the selected P1 meter to the native HA Energy Dashboard or import compatible HA source mappings into Smart Energy.": "Verbinden Sie das ausgewählte P1-Messgerät mit dem nativen HA Energy Dashboard oder importieren Sie kompatible HA-Quellenzuordnungen in Smart Energy.",
    "Connect your SmartHomeShop account to get dynamic prices, cheapest-hours planning and automated control.": "Verbinden Sie Ihr SmartHomeShop-Konto, um dynamische Preise, günstigste Stundenplanung und automatisierte Steuerung zu erhalten.",
    "Connect your SmartHomeShop account, select a contract and choose the P1 meter used across Smart Energy.": "Verbinden Sie Ihr SmartHomeShop-Konto, wählen Sie einen Vertrag aus und wählen Sie das P1-Messgerät, das für Smart Energy verwendet wird.",
    "Connect your SmartHomeShop.io devices via ESPHome, then add this integration via Settings → Devices & Services": "Verbinden Sie Ihre SmartHomeShop.io-Geräte über ESPHome und fügen Sie diese Integration über Einstellungen → Geräte & Dienste hinzu",
