    "Connected, but this location has no active energy contract yet. Add one in your SmartHomeShop account to see prices.": "Verbunden, aber dieser Standort hat noch keinen aktiven Energievertrag. Fügen Sie eine in Ihrem SmartHomeShop-Konto hinzu, um die Preise zu sehen.",
