    "Dynamic prices are unavailable right now, so no new cheap block can be planned. These schedules stay saved and start again as soon as prices return.": "Dynamische Preise sind derzeit nicht verfügbar, so dass kein neuer billiger Block geplant werden kann. Diese Zeitpläne bleiben gespeichert und beginnen erneut, sobald die Preise zurückkehren.",
