    "One connection unlocks live dynamic prices, cheapest-hours planning, deadline schedules and battery control. Create a free API key in your account and paste it here.": "Eine Verbindung ermöglicht dynamische Live-Preise, günstigste Stundenplanung, Terminpläne und Batteriesteuerung. Erstellen Sie einen kostenlosen API-Schlüssel in Ihrem Konto und fügen Sie ihn hier ein.",
