    "Preferred: select a writable inverter active-power/output-limit number. Only use the switch fallback with the inverter manufacturer's safe enable control or a dedicated helper that calls that control. Never switch the inverter's AC supply with a smart plug, relay or contactor. The fallback can briefly export during every test start.": "Bevorzugt: Wählen Sie eine beschreibbare Wechselrichter Active-Power / Output-Limit-Nummer. Verwenden Sie das Switch-Fallback nur mit der Safe Enable-Steuerung des Wechselrichterherstellers oder einem dedizierten Helfer, der diese Steuerung aufruft. Schalten Sie niemals die Wechselrichterversorgung mit einem intelligenten Stecker, Relais oder Schütz. Der Fallback kann bei jedem Teststart kurzzeitig exportiert werden.",
