    "Prices follow the active contract for this location and update by themselves when you change it in your SmartHomeShop account.": "Die Preise folgen dem aktiven Vertrag für diesen Standort und aktualisieren sich selbst, wenn Sie ihn in Ihrem SmartHomeShop-Konto ändern.",
