    "Radar unavailable": "Radar nicht verfügbar",
    "Raise a thermostat setpoint during the cheapest block to store comfort, then lower it during the price peak. Uses the home as thermal storage.": "Erhöhen Sie einen Thermostat-Sollwert während des billigsten Blocks, um Komfort zu speichern, und senken Sie ihn dann während des Preisspitzenwertes. Nutzt das Haus als Wärmespeicher.",
    "Raise the limit, or immediately restart a paused inverter, when grid import exceeds this value.": "Heben Sie das Limit an oder starten Sie sofort einen pausierten Wechselrichter neu, wenn der Netzimport diesen Wert überschreitet.",
