    "Remove": "Entfernen",
    "Remove both the SmartHomeShop link and ESPHome configuration. This does not erase the firmware or delete the node from the ESPHome dashboard.": "Entfernen Sie sowohl den SmartHomeShop Link als auch die ESPHome Konfiguration. Dadurch wird die Firmware nicht gelöscht oder der Knoten aus dem ESPHome-Dashboard gelöscht.",
    "Remove completely from Home Assistant": "Vollständig aus Home Assistant entfernen",
