    "Restart Home Assistant once to load the newly added cumulative import, export and normalised gas sensors needed by the Energy Dashboard.": "Starten Sie Home Assistant einmalig, um die neu hinzugefügten kumulativen Import-, Export- und normalisierten Gassensoren zu laden, die vom Energy Dashboard benötigt werden.",
    "Restart Home Assistant to finish unloading it.": "Starten Sie Home Assistant neu, um das Entladen abzuschließen.",
