    "Run an opportunistic load whenever the price is at or below the daily average, and stop it when it rises above.": "Führen Sie eine opportunistische Last aus, wenn der Preis am oder unter dem Tagesdurchschnitt liegt, und stoppen Sie ihn, wenn er übersteigt.",
