    "Schedule saved, but its sensor is not ready yet. Reopen and save again to create the automation.": "Zeitplan gespeichert, aber sein Sensor ist noch nicht bereit. Öffnen und speichern Sie erneut, um die Automatisierung zu erstellen.",
