    "Select a control entity before enabling automatic control.": "Wählen Sie eine Steuerungseinheit aus, bevor Sie die automatische Steuerung aktivieren.",
    "Select a sensor when your inverter exposes the usable battery capacity. Its live value overrides the fixed value below.": "Wählen Sie einen Sensor aus, wenn Ihr Wechselrichter die nutzbare Batteriekapazität freigibt. Sein Live-Wert überschreibt den Festwert unten.",
    "Select a sensor, then walk to four reliable outer positions.": "Wählen Sie einen Sensor und gehen Sie dann zu vier zuverlässigen äußeren Positionen.",
