    "Separate parts belong to the same zone and share its presence state.": "Getrennte Teile gehören zur gleichen Zone und teilen ihren Anwesenheitszustand.",
    "Server URL - leave empty for the default. Only change this for self-hosting or local testing.": "Server-URL - für den Standard leer lassen. Ändern Sie dies nur für Selbst-Hosting oder lokale Tests.",
    "Set both maximum charge and discharge power.": "Stellen Sie sowohl die maximale Lade- als auch die Entladeleistung ein.",
