    "Setting the meter reading is done on the device itself and requires the latest firmware. Update the firmware of your kit (via": "Die Einstellung der Zählerablesung erfolgt auf dem Gerät selbst und erfordert die neueste Firmware. Aktualisieren Sie die Firmware Ihres Kits (via)",
