    "Your API key works, but the selected location has no active energy contract, so there are no prices to plan against. Add or activate a contract in your SmartHomeShop account, or pick another location in Settings.": "Ihr API-Schlüssel funktioniert, aber der ausgewählte Standort hat keinen aktiven Energievertrag, so dass keine Preise zu planen sind. Fügen Sie einen Vertrag in Ihrem SmartHomeShop-Konto hinzu oder aktivieren Sie ihn oder wählen Sie einen anderen Speicherort in den Einstellungen aus.",
    "Your P1 meter covers the grid. If you have solar panels or a home battery, connect their sensors so the Energy tab shows real surplus and state of charge. You can always do this later from Settings.": "Ihr P1-Messgerät deckt das Netz ab. Wenn Sie Solarmodule oder eine Hausbatterie haben, schließen Sie deren Sensoren an, damit die Registerkarte Energie den tatsächlichen Überschuss und den Ladezustand anzeigt. Sie können dies später immer über Einstellungen tun.",
    "Your P1 meter only sees the grid. Connect your solar and battery entities (you already have them in Home Assistant) so we can see real solar surplus and your battery's charge level.": "Ihr P1-Messgerät sieht nur das Gitter. Verbinden Sie Ihre Solar- und Batterieeinheiten (Sie haben sie bereits in Home Assistant), damit wir einen echten Solarüberschuss und den Ladezustand Ihrer Batterie sehen können.",
