    "SmartHomeShop Energy is pinned to a specific contract. Pick a location above to follow its active contract instead.": "Autres L'énergie est liée à un contrat spécifique. Choisissez un emplacement ci-dessus pour suivre son contrat actif.",
    "SmartHomeShop not linked": "SmartHomeShop non lié",
