    "Use automatic": "Utiliser automatiquement",
    "Use firmware mounting": "Utiliser le firmware",
    "Use measured area": "Utiliser la surface mesurée",
    "Use solar surplus for a device": "Utiliser l'excédent solaire pour un appareil",
    "Use the lowest value accepted by the inverter. A small non-zero limit is safer for many models.": "Utilisez la valeur la plus basse acceptée par l'onduleur. Une petite limite non nulle est plus sûre pour de nombreux modèles.",
    "Used for the smart-savings estimate and the fuse guard below.": "Utilisé pour l'estimation des économies intelligentes et le garde-fusée ci-dessous.",
    "Used to stop charging at the target and to protect the reserve in battery arbitrage.": "Utilisé pour arrêter la charge à la cible et protéger la réserve dans l'arbitrage de batterie.",
    "Used when no capacity entity is selected or when that entity is temporarily unavailable.": "Utilisée lorsqu'aucune entité de capacité n'est sélectionnée ou lorsqu'elle est temporairement indisponible.",
    "Used when no load forecast is selected.": "Utilisé quand aucune prévision de charge n'est sélectionnée.",
    "Usually 100 for a percentage entity, or the inverter maximum for a watt-based entity.": "Habituellement 100 pour une entité en pourcentage, ou le maximum de l'onduleur pour une entité en watt.",
    "Visualization only": "Visualisation seulement",
    "Wait for the LD2460 installation settings before pushing zones": "Wait pour les paramètres d'installation de LD2460 avant de pousser les zones",
    "Waiting for capacity": "Waiting pour la capacité",
    "Waiting for confirmed price data": "Waiting pour les données de prix confirmées",
    "Waiting for the first complete plan.": "Waiting pour le premier plan complet.",
    "Walk to each edge of the area the sensor can reliably detect. Stand still and select Mark. Your position is averaged over 5 seconds.": "Walk à chaque bord de la zone que le capteur peut détecter de manière fiable. Restez immobile et sélectionnez Mark. Votre position est moyenne sur 5 secondes.",
    "Wall mounted": "Wall monté",
    "Walls": "Murs",
    "Water": "Eau",
    "Water has been flowing non-stop - possible leak or running tap.": "Water coule sans arrêt - fuite possible ou robinet de fonctionnement.",
    "Water is being used during the night.": "Water est utilisé pendant la nuit.",
    "Water leak sensor wet": "Capteur de fuite Water mouillé",
    "water monitoring, leak detection and usage insights": "surveillance de l'eau, détection des fuites et perspectives d'utilisation",
    "water monitoring, leak detection, energy costs and insights": "surveillance de l'eau, détection des fuites, coûts énergétiques et perspectives",
    "Water today": "Water aujourd'hui",
    "Water total": "Total Water",
    "Welcome! Connect your SmartHomeShop account": "Welcome ! Connectez votre compte SmartHomeShop",
    "What smart energy earned": "Ce que Smart Energy a rapporté",
    "When the feed-in price goes negative (you would pay to export), switch on a diversion load to self-consume instead. Off again when feed-in is positive.": "Lorsque le tarif d’injection devient négatif et que vous paieriez pour injecter, activez plutôt une charge afin de consommer l’énergie sur place. Désactivez-la de nouveau lorsque le tarif redevient positif.",
    "Width (cm)": "Largeur (cm)",
    "Window type": "Type de fenêtre",
    "Writable inverter limit or safe enable control": "Limite d'onduleur Writable ou contrôle sécurisé",
    "You are measuring the sensor, not the room": "Vous mesurez le capteur, pas la pièce",
    "You have unsaved changes in the Room Designer. Discard them?": "Vous avez des modifications non enregistrées dans le Room Designer. Les rejeter ?",
    "You have unsaved changes. Discard them?": "Vous avez des changements non sauvés. Les rejeter ?",
    "You need an administrator account to create automations.": "Vous avez besoin d'un compte administrateur pour créer des automatismes.",
    "Your API key works, but the selected location has no active energy contract, so there are no prices to plan against. Add or activate a contract in your SmartHomeShop account, or pick another location in Settings.": "Votre clé API fonctionne, mais l'emplacement sélectionné n'a pas de contrat d'énergie actif, donc il n'y a pas de prix contre. Ajoutez ou activez un contrat dans votre compte SmartHomeShop, ou choisissez un autre emplacement dans Paramètres.",
    "Your P1 meter covers the grid. If you have solar panels or a home battery, connect their sensors so the Energy tab shows real surplus and state of charge. You can always do this later from Settings.": "Votre compteur P1 couvre la grille. Si vous avez des panneaux solaires ou une batterie à la maison, connectez leurs capteurs afin que l'onglet Énergie affiche un excédent réel et l'état de charge. Vous pouvez toujours le faire plus tard à partir de Paramètres.",
    "Your P1 meter only sees the grid. Connect your solar and battery entities (you already have them in Home Assistant) so we can see real solar surplus and your battery's charge level.": "Votre compteur P1 ne voit que la grille. Connectez vos entités solaires et batteries (vous les avez déjà en Home Assistant) afin que nous puissions voir le surplus solaire réel et le niveau de charge de votre batterie.",
    "Your polygon zone is drawn! Choose what type this zone should be.": "Votre zone de polygone est tracée ! Choisissez quel type cette zone devrait être.",
    "Your return value is higher than today's import cost.": "Votre valeur de retour est plus élevée que le coût d'importation actuel.",
    "Your sensors are detected automatically.": "Vos capteurs sont détectés automatiquement.",
