    "One connection unlocks live dynamic prices, cheapest-hours planning, deadline schedules and battery control. Create a free API key in your account and paste it here.": "Una conexión desbloquea precios dinámicos en vivo, planificación de las horas más baratas, horarios y control de baterías. Cree una clave de API gratuita en su cuenta y pega aquí.",
    "One-click automations for this device - pick the ones you want and choose where the notification goes. Each becomes a normal Home Assistant automation you can fine-tune later in the automation editor.": "Automatizaciones de un clic para este dispositivo - elegir las que desea y elegir dónde va la notificación. Cada uno se convierte en una automatización Home Assistant normal que puede ajustar más adelante en el editor de automatización.",
    "Online": "En línea",
    "Only grid power is connected. Add your solar and battery entities to see production, storage and state of charge.": "Sólo la energía de la red está conectada. Agregue sus entidades solares y baterías para ver la producción, almacenamiento y estado de carga.",
