    "State-of-charge sensor": "Sensor de estado de carga",
    "Steer devices around prices and solar production. Loads can run in cheap or surplus hours, while inverter output can be reduced safely to avoid unwanted export. Each setup creates a normal, editable Home Assistant automation with restart recovery and fail-safe behaviour.": "Dispositivos de control alrededor de precios y producción solar. Las cargas pueden correr en horas baratas o excedentes, mientras que la salida del inversor puede reducirse con seguridad para evitar la exportación no deseada. Cada configuración crea una automatización Home Assistant normal y editable con recuperación de reiniciar y comportamiento inseguro.",
    "Surplus needed": "Superávit necesario",
    "Switch a deferrable load (boiler, pump, ventilation) on during the cheapest contiguous block of the day and off when it ends.": "Cambiar una carga aplazable (boiler, bomba, ventilación) durante el bloque contiguo más barato del día y cuando termine.",
    "Switch a load off when the price level hits its daily peak and back on when it drops. Trims the most expensive hours.": "Apague una carga cuando el nivel de precio golpee su pico diario y vuelva a encender cuando se baja. Las horas más caras.",
    "Switch a load on when the house exports more than it needs, and off when you would start importing - with hysteresis + dwell so it does not flap.": "Intercambia una carga cuando la casa exporta más de lo que necesita, y fuera cuando comenzaría a importar - con la histeresis + mora por lo que no se colapsa.",
    "Switch off after": "Apaga después.",
