    "That API key is invalid or was revoked.": "Esa clave de API es inválida o fue revocada.",
    "The active contract for today has expired or is not set, so no prices are shown. Pin a specific contract above, or add an active contract in your SmartHomeShop account.": "El contrato activo para hoy ha expirado o no está fijado, por lo que no se muestran precios. Pin un contrato específico arriba, o añadir un contrato activo en su cuenta SmartHomeShop.",
    "The active tariff is unknown, so SmartHomeShop never guesses.": "El arancel activo es desconocido, por lo que SmartHomeShop nunca adivina.",
    "The combined P1 energy sensors are not available yet. Restart Home Assistant after updating the integration.": "Los sensores combinados de energía P1 no están disponibles todavía. Reinicie Home Assistant después de actualizar la integración.",
    "The connection check timed out.": "El cheque de conexión se acabó.",
    "The device stays visible here as “Not linked” because ESPHome still supplies it. You can link it to SmartHomeShop again later.": "El dispositivo se mantiene visible aquí como “No vinculado” porque ESPHome todavía lo suministra. Puede conectarlo a SmartHomeShop otra vez más tarde.",
    "The Energy Dashboard already uses the recommended SmartHomeShop entities.": "El panel de energía ya utiliza las entidades recomendadas SmartHomeShop.",
    "The energy price sensors are not ready yet. Try again in a moment.": "Los sensores de precio energético aún no están listos. Inténtalo de nuevo en un momento.",
    "The existing automation has no supported target entities. Select one before saving.": "La automatización existente no cuenta con entidades de destino apoyadas. Seleccione uno antes de guardar.",
    "The green \"IN\" arrow shows the direction into the room, the red \"OUT\" arrow the direction out.": "La flecha verde \"IN\" muestra la dirección en la habitación, la flecha roja \"OUT\" hacia fuera.",
